(4604617, 664720, 80904, '<td valign="top">I have this fish in my Aquarium. I give you a 6 just because its very difficult to take a picture of this fish. Good job</td>', 'I have this fish in my Aquarium. I give you a 6 just because its very difficult to take a picture of this fish. Good job', '2008-04-02 01:27:36.000000', NULL, 1),
(4604649, 664520, 72068, '<td valign="top">I really, really like this shot.</td>', 'I really, really like this shot.', '2008-04-02 01:31:16.000000', NULL, 1),
(4604653, 663838, 72068, '<td valign="top">The red strikes me as being quite a warm tone, otherwise, nice shot</td>', 'The red strikes me as being quite a warm tone, otherwise, nice shot', '2008-04-02 01:31:51.000000', NULL, 1),
(4604664, 662534, 72068, '<td valign="top">I have no idea what this is, but whatever it might be, it made a great photo!</td>', 'I have no idea what this is, but whatever it might be, it made a great photo!', '2008-04-02 01:34:05.000000', NULL, 1),
(4604676, 665096, 72068, '<td valign="top">Wow, everything about this shot is very good, I love the way the trees almost create a border to the shot, drawing your eye up to the peak of the mountain - it''s only when you look twice you see the nice reflection in the water of the trees, and the wispy clouds in the sky.</td>', 'Wow, everything about this shot is very good, I love the way the trees almost create a border to the shot, drawing your eye up to the peak of the mountain - it''s only when you look twice you see the nice reflection in the water of the trees, and the wispy clouds in the sky.', '2008-04-02 01:36:27.000000', NULL, 1),
(4604683, 665017, 72068, '<td valign="top">I have to say, this is a nice shot, but - I think purple is a warmer colour - well, the fact it''s a rose doesn''t help. Roses are associated with love and affection, which in turn I tend to relate to warmth rather than coolness.</td>', 'I have to say, this is a nice shot, but - I think purple is a warmer colour - well, the fact it''s a rose doesn''t help. Roses are associated with love and affection, which in turn I tend to relate to warmth rather than coolness.', '2008-04-02 01:38:11.000000', NULL, 1),
