INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4606616, 664882, 85848, '<td valign="top">Set-ups like this suffer more than usual from small flaws of composition.  E.g., crop the the lavender''s diagonal on the right.</td>', 'Set-ups like this suffer more than usual from small flaws of composition.  E.g., crop the the lavender''s diagonal on the right.', '2008-04-02 12:03:35.000000', NULL, 1),
(4606618, 664870, 85848, '<td valign="top">Washed out &amp; grainy.</td>', 'Washed out & grainy.', '2008-04-02 12:04:14.000000', NULL, 1),
(4606625, 664962, 85848, '<td valign="top">Interesting setting, but cluttered.  Doesn''t appear "cool" to me.</td>', 'Interesting setting, but cluttered.  Doesn''t appear "cool" to me.', '2008-04-02 12:06:33.000000', NULL, 1),
(4606627, 663733, 85848, '<td valign="top">Neat cool still-life.  Crop the right side?</td>', 'Neat cool still-life.  Crop the right side?', '2008-04-02 12:07:10.000000', NULL, 1),
(4606631, 664897, 85848, '<td valign="top">Very interesting kaleidoscope of colors.  A bit too muted, perhaps?  Add some contrast.</td>', 'Very interesting kaleidoscope of colors.  A bit too muted, perhaps?  Add some contrast.', '2008-04-02 12:08:06.000000', NULL, 1),
(4606636, 663730, 85848, '<td valign="top">Would work much better as a panorama format.</td>', 'Would work much better as a panorama format.', '2008-04-02 12:09:31.000000', NULL, 1),
(4606644, 664713, 85848, '<td valign="top">Good, deep colors.  Set-ups need to be perfectly cropped...too much black at the top, cut-off of the reflection below, both hurt.</td>', 'Good, deep colors.  Set-ups need to be perfectly cropped...too much black at the top, cut-off of the reflection below, both hurt.', '2008-04-02 12:10:47.000000', NULL, 1),
(4606646, 663122, 85848, '<td valign="top">Cool young lady, nicely arrangeds.</td>', 'Cool young lady, nicely arrangeds.', '2008-04-02 12:11:11.000000', NULL, 1),
(4606663, 662626, 85848, '<td valign="top">Color balance is off.  Browns muted. Tilted.  Crop the top to 3x2.</td>', 'Color balance is off.  Browns muted. Tilted.  Crop the top to 3x2.', '2008-04-02 12:16:11.000000', NULL, 1),
(4606692, 665113, 85848, '<td valign="top">Very cool storm!  The super-wide POV works really well.  Slight tilt detracts, and could use a bit more snap in the exposure.</td>', 'Very cool storm!  The super-wide POV works really well.  Slight tilt detracts, and could use a bit more snap in the exposure.', '2008-04-02 12:22:15.000000', NULL, 1),
(4606695, 663801, 54431, '<td valign="top">I love how this was shot! Nice job. I like how the black frames the blue water and sky. The window really pulls you in, making you wonder what else is out there. The shadows on the ledge also add an interesting element.</td>', 'I love how this was shot! Nice job. I like how the black frames the blue water and sky. The window really pulls you in, making you wonder what else is out there. The shadows on the ledge also add an interesting element.', '2008-04-02 12:23:27.000000', NULL, 1),
(4606702, 664681, 85848, '<td valign="top">Cool night, indeed.  Color balance is bit magenta on my corrected monitor.  Crop the top down to 4x3.</td>', 'Cool night, indeed.  Color balance is bit magenta on my corrected monitor.  Crop the top down to 4x3.', '2008-04-02 12:26:53.000000', NULL, 1),
(4606704, 663191, 85848, '<td valign="top">Cool rendering, but blown-out skin tones &amp; eyes.</td>', 'Cool rendering, but blown-out skin tones & eyes.', '2008-04-02 12:27:27.000000', NULL, 1),
(4606716, 662468, 54431, '<td valign="top">Very simple. I find it interesting that without a main subject in this piece, I still find myself looking more and more into this shot. The blues are very calming and the texture and shades of the ice add so much to this piece. I think this would look terrific blown up to a large size. Great shot!</td>', 'Very simple. I find it interesting that without a main subject in this piece, I still find myself looking more and more into this shot. The blues are very calming and the texture and shades of the ice add so much to this piece. I think this would look terrific blown up to a large size. Great shot!', '2008-04-02 12:32:02.000000', NULL, 1),
(4606730, 664550, 54431, '<td valign="top">Good composition but it looks to me as though there might have been too much post processing done on this shot...I can also see the halo on the tree which I''m not too crazy about.</td>', 'Good composition but it looks to me as though there might have been too much post processing done on this shot...I can also see the halo on the tree which I''m not too crazy about.', '2008-04-02 12:37:42.000000', NULL, 1),
(4606735, 662398, 54431, '<td valign="top">Nice texture and composition</td>', 'Nice texture and composition', '2008-04-02 12:40:05.000000', NULL, 1),
(4606761, 664010, 54431, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2008-04-02 12:47:27.000000', NULL, 1),
(4606774, 663723, 85848, '<td valign="top">Neat abstract curves &amp; forms.  Could stand a bit more exposure, contrast.</td>', 'Neat abstract curves & forms.  Could stand a bit more exposure, contrast.', '2008-04-02 12:49:56.000000', NULL, 1),
(4606777, 664622, 85848, '<td valign="top">Cool?  Seems the opposite to me.  Nice flower pic, though.</td>', 'Cool?  Seems the opposite to me.  Nice flower pic, though.', '2008-04-02 12:50:34.000000', NULL, 1),
(4606784, 664028, 85848, '<td valign="top">Some interesting elements, but overall cluttered &amp; confusing.  The hyper-contrast is distracting too.  Also I don''t see this as saying "cool."</td>', 'Some interesting elements, but overall cluttered & confusing.  The hyper-contrast is distracting too.  Also I don''t see this as saying "cool."', '2008-04-02 12:51:46.000000', NULL, 1),
(4606787, 664151, 85848, '<td valign="top">Neat cloud shot.  Blown-out in the critical area, tilted.</td>', 'Neat cloud shot.  Blown-out in the critical area, tilted.', '2008-04-02 12:52:40.000000', NULL, 1),
(4606801, 664989, 85848, '<td valign="top">Cool, dude!  Rendering is kinda bland, but points for interpretation.</td>', 'Cool, dude!  Rendering is kinda bland, but points for interpretation.', '2008-04-02 12:57:33.000000', NULL, 1),
(4606858, 664782, 85848, '<td valign="top">Cool abstract.  Better at the bottom than the top.</td>', 'Cool abstract.  Better at the bottom than the top.', '2008-04-02 13:09:05.000000', NULL, 1),
(4606875, 664877, 26001, '<td valign="top">absolutely gorgeous cyan. i wonder how did you gt the darker blue inside the glass. top middle one still has cyan on the back face and uneven gradation suggests they are not filled with liquid either.<br/>dpc history suggests, this one should be the podium contender.</td>', 'absolutely gorgeous cyan. i wonder how did you gt the darker blue inside the glass. top middle one still has cyan on the back face and uneven gradation suggests they are not filled with liquid either.dpc history suggests, this one should be the podium contender.', '2008-04-02 13:13:52.000000', NULL, 1),
