INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4609240, 664870, 19799, '<td valign="top">This shot doesn''t seem to have much appeal to it. Also, a boost in contrast would help and it seems a bit noisy.</td>', 'This shot doesn''t seem to have much appeal to it. Also, a boost in contrast would help and it seems a bit noisy.', '2008-04-02 23:57:44.000000', NULL, 1),
(4609243, 664762, 19799, '<td valign="top">This is a nice capture. I like the composition of this shot a lot!!!</td>', 'This is a nice capture. I like the composition of this shot a lot!!!', '2008-04-02 23:58:32.000000', NULL, 1),
(4609249, 663762, 19799, '<td valign="top">This is a great capture. Would have liked it better in the portrait orientation instead of the landscape orientation though.</td>', 'This is a great capture. Would have liked it better in the portrait orientation instead of the landscape orientation though.', '2008-04-02 23:59:30.000000', NULL, 1),
(4609256, 665112, 19799, '<td valign="top">Great use of snow to frame a shot. What was framed by the snow lacks interest though.</td>', 'Great use of snow to frame a shot. What was framed by the snow lacks interest though.', '2008-04-03 00:00:39.000000', NULL, 1),
(4609260, 664248, 19799, '<td valign="top">Doesn''t seem to be a very sharp photo. Seems a bit soft.</td>', 'Doesn''t seem to be a very sharp photo. Seems a bit soft.', '2008-04-03 00:01:17.000000', NULL, 1),
(4609267, 664024, 19799, '<td valign="top">This must have been shot at a slooow shutter speed. The cloud like water is a very nice touch.</td>', 'This must have been shot at a slooow shutter speed. The cloud like water is a very nice touch.', '2008-04-03 00:02:36.000000', NULL, 1),
(4609270, 664890, 19799, '<td valign="top">Cold outside...yes. Has the cool challenge theme...not really seeing it.</td>', 'Cold outside...yes. Has the cool challenge theme...not really seeing it.', '2008-04-03 00:03:31.000000', NULL, 1),
(4609278, 664513, 19799, '<td valign="top">Seems out of focus and seeing the entire glass or eliminating the stem would be better IMO.</td>', 'Seems out of focus and seeing the entire glass or eliminating the stem would be better IMO.', '2008-04-03 00:04:36.000000', NULL, 1),
(4609282, 664960, 19799, '<td valign="top">The flower in focus is too centered for my liking. Maybe using the rule of 1/3 to crop if differently would make it more aesthetically pleasing. Also seems to be underexposed.</td>', 'The flower in focus is too centered for my liking. Maybe using the rule of 1/3 to crop if differently would make it more aesthetically pleasing. Also seems to be underexposed.', '2008-04-03 00:05:59.000000', NULL, 1),
(4609293, 665099, 19799, '<td valign="top">The branches on the tree seem to be more in focus than the bride. There is too much competing for attention in this shot when I think the shot is intended to bring attention to the bride.</td>', 'The branches on the tree seem to be more in focus than the bride. There is too much competing for attention in this shot when I think the shot is intended to bring attention to the bride.', '2008-04-03 00:07:16.000000', NULL, 1),
(4609300, 662505, 19799, '<td valign="top">I think a portrait crop would have worked better than the landscape crop.</td>', 'I think a portrait crop would have worked better than the landscape crop.', '2008-04-03 00:08:33.000000', NULL, 1),
(4609304, 664953, 19799, '<td valign="top">Can''t really tell what this shot is about or what the meaning behind it is.</td>', 'Can''t really tell what this shot is about or what the meaning behind it is.', '2008-04-03 00:09:11.000000', NULL, 1),
(4609313, 663834, 19799, '<td valign="top">Seems a bit soft. Maybe this was the intent but I think a bump in contrast would be better.</td>', 'Seems a bit soft. Maybe this was the intent but I think a bump in contrast would be better.', '2008-04-03 00:10:31.000000', NULL, 1),
(4609421, 664125, 90074, '<td valign="top">I think you should of not put the child in the picture, but other wise good pictue.</td>', 'I think you should of not put the child in the picture, but other wise good pictue.', '2008-04-03 00:41:35.000000', NULL, 1),
(4609428, 663699, 90074, '<td valign="top">beautiful picture, 8.</td>', 'beautiful picture, 8.', '2008-04-03 00:42:57.000000', NULL, 1),
(4609434, 664658, 90074, '<td valign="top">I love the reflections. 8</td>', 'I love the reflections. 8', '2008-04-03 00:44:12.000000', NULL, 1),
(4609441, 664782, 90074, '<td valign="top">Nice "Abstract" I dont know what it is.</td>', 'Nice "Abstract" I dont know what it is.', '2008-04-03 00:48:08.000000', NULL, 1),
(4609447, 663963, 88756, '<td valign="top">Is it cool or is it hot?</td>', 'Is it cool or is it hot?', '2008-04-03 00:50:58.000000', NULL, 1),
(4609452, 664960, 90074, '<td valign="top">I think that you should of tried to get the inside of the flower, and if there was a road where you were standing it was still a great photograph. 7.</td>', 'I think that you should of tried to get the inside of the flower, and if there was a road where you were standing it was still a great photograph. 7.', '2008-04-03 00:52:50.000000', NULL, 1),
(4609461, 664877, 90074, '<td valign="top">Great picture, what is it? 7.</td>', 'Great picture, what is it? 7.', '2008-04-03 00:57:28.000000', NULL, 1),
(4609540, 664402, 90380, '<td valign="top">Nice capture, and very good pose you got him in, almost like he''s enjoying his photo op!  It''s an interesting one, but the few things I think could be improved upon are that it is slightly overexposed, so the bird''s head is blown out.  I also would have left a little bit more space on the left side of the bird. The left-leaning composition makes the image appear, well, left-leaning, and makes it feel somewhat unbalanced.</td>', 'Nice capture, and very good pose you got him in, almost like he''s enjoying his photo op!  It''s an interesting one, but the few things I think could be improved upon are that it is slightly overexposed, so the bird''s head is blown out.  I also would have left a little bit more space on the left side of the bird. The left-leaning composition makes the image appear, well, left-leaning, and makes it feel somewhat unbalanced.', '2008-04-03 01:28:26.000000', NULL, 1),
(4609549, 664125, 90380, '<td valign="top">Nice colour combination. I think this would have more impact if the child was more in focus, as I would like to see his facial expression more clearly. He''s a cutey!</td>', 'Nice colour combination. I think this would have more impact if the child was more in focus, as I would like to see his facial expression more clearly. He''s a cutey!', '2008-04-03 01:30:29.000000', NULL, 1),
(4609568, 664550, 90380, '<td valign="top">It looks like an interesting subject and well composed photo, but I''m not sure I like the effect that has been added. Sorry.</td>', 'It looks like an interesting subject and well composed photo, but I''m not sure I like the effect that has been added. Sorry.', '2008-04-03 01:42:04.000000', NULL, 1),
(4609597, 664956, 37252, '<td valign="top">I really like the image - but why that frame? I feel the frame is going to really hurt your score on this.</td>', 'I really like the image - but why that frame? I feel the frame is going to really hurt your score on this.', '2008-04-03 02:03:08.000000', NULL, 1),
(4609616, 664207, 37252, '<td valign="top">lol. Cute idea, wish I had an egg. :P</td>', 'lol. Cute idea, wish I had an egg. :P', '2008-04-03 02:20:34.000000', NULL, 1),
