(4609680, 664520, 61396, '<td valign="top">The yellow touches emphasizing the cool blue is great.</td>', 'The yellow touches emphasizing the cool blue is great.', '2008-04-03 03:00:20.000000', NULL, 1),
(4609681, 664897, 39349, '<td valign="top">Nice colors and exposure control is right on. My only suggestion would be to work with the composition a bit more, perhaps get lower to the ground or higher up, my eye is left wandering around. 6</td>', 'Nice colors and exposure control is right on. My only suggestion would be to work with the composition a bit more, perhaps get lower to the ground or higher up, my eye is left wandering around. 6', '2008-04-03 03:02:11.000000', NULL, 1),
(4609683, 664698, 39349, '<td valign="top">WOW nice mirror reflections! Pretty centered composition which I''m not sure works for this shot, there are a lot of interesting subjects just begging to be the center of attention in this shot. Exposure is on the money and you fit the challenge theme. 6</td>', 'WOW nice mirror reflections! Pretty centered composition which I''m not sure works for this shot, there are a lot of interesting subjects just begging to be the center of attention in this shot. Exposure is on the money and you fit the challenge theme. 6', '2008-04-03 03:05:44.000000', NULL, 1),
(4609686, 662922, 39349, '<td valign="top">I''m diggin it, but I''m a little partial to painting with light. ;)</td>', 'I''m diggin it, but I''m a little partial to painting with light. ;)', '2008-04-03 03:06:34.000000', NULL, 1),
(4609688, 663699, 39349, '<td valign="top">Nice leading lines here, with the sky being a bit blown out I would wonder what this shot would look like in black and white? Nice work and good luck in the challenge.</td>', 'Nice leading lines here, with the sky being a bit blown out I would wonder what this shot would look like in black and white? Nice work and good luck in the challenge.', '2008-04-03 03:07:44.000000', NULL, 1),
(4609696, 664024, 39349, '<td valign="top">This is a super cool (no pun intended) shot. It had to be a tricky exposure as well with the water being in the shadow and not blowing out the sky. I wonder if you used a graduated n/d filter? <br/> <br/>Nice work; high marks.</td>', 'This is a super cool (no pun intended) shot. It had to be a tricky exposure as well with the water being in the shadow and not blowing out the sky. I wonder if you used a graduated n/d filter?  Nice work; high marks.', '2008-04-03 03:11:32.000000', NULL, 1),
(4609700, 664748, 39349, '<td valign="top">Beautiful shot; not seeing any "cool colors" here unfortunately.</td>', 'Beautiful shot; not seeing any "cool colors" here unfortunately.', '2008-04-03 03:13:31.000000', NULL, 1),
(4609706, 664785, 39349, '<td valign="top">Those are cool mugs.<br/>.<br/>.<br/>.<br/>.<br/>sorry had to..</td>', 'Those are cool mugs.....sorry had to..', '2008-04-03 03:22:26.000000', NULL, 1),
