(4610664, 664980, 89431, '<td valign="top">I like the different look of the glasses, it cretaes a look of different textures. And the blue hue looks really nice with these pieces.</td>', 'I like the different look of the glasses, it cretaes a look of different textures. And the blue hue looks really nice with these pieces.', '2008-04-03 11:52:56.000000', NULL, 1),
(4610670, 662461, 89431, '<td valign="top">Maybe you accidentally entered this in the wrong challenge, so I''m not going to point out the obvious. The distortion of the strawberries in the glass looks nice and i like how you were very creative witht he water surrounding everything with it. The angle also creates interest but i think i would have liked it better if you didn''t cut the bottom of the glass off. (i didn''t score this, i figure you''re probably suffering enough) Nice photo, wrong challenge.</td>', 'Maybe you accidentally entered this in the wrong challenge, so I''m not going to point out the obvious. The distortion of the strawberries in the glass looks nice and i like how you were very creative witht he water surrounding everything with it. The angle also creates interest but i think i would have liked it better if you didn''t cut the bottom of the glass off. (i didn''t score this, i figure you''re probably suffering enough) Nice photo, wrong challenge.', '2008-04-03 11:56:18.000000', NULL, 1),
(4610681, 664513, 89431, '<td valign="top">The glass itself looks a little dirty, maybe thats just the liquid inside. I like how you added the lemon for a complementary color, but since the photo is so dark it more draws my attention all to it instead of bring out the blue liquid.</td>', 'The glass itself looks a little dirty, maybe thats just the liquid inside. I like how you added the lemon for a complementary color, but since the photo is so dark it more draws my attention all to it instead of bring out the blue liquid.', '2008-04-03 11:59:04.000000', NULL, 1),
(4610687, 664402, 89431, '<td valign="top">The bright blue of the water is nice but the bird''s head looks a bit bleache out, maybe you shot this in a time of day were the light was at it''s most intense and then this could have been fixed with a little patience to wait for the right light. (i guess the bird would fly away though...)</td>', 'The bright blue of the water is nice but the bird''s head looks a bit bleache out, maybe you shot this in a time of day were the light was at it''s most intense and then this could have been fixed with a little patience to wait for the right light. (i guess the bird would fly away though...)', '2008-04-03 12:02:12.000000', NULL, 1),
(4610694, 664953, 89431, '<td valign="top">Too bad about the date and time down there... other than that your flash made the light too intense and it got rid of all the detail and shadow creating that cut and paste look. The colors, for me, just aren''t cool enough either.</td>', 'Too bad about the date and time down there... other than that your flash made the light too intense and it got rid of all the detail and shadow creating that cut and paste look. The colors, for me, just aren''t cool enough either.', '2008-04-03 12:04:04.000000', NULL, 1),
(4610703, 664016, 89431, '<td valign="top">i would like to know what this is for. I do like the subject, the gold is dark enough that it enhances the blue instead of taking it away. Those hotspots on the other hand do distract a bit, bt other than that i like it.</td>', 'i would like to know what this is for. I do like the subject, the gold is dark enough that it enhances the blue instead of taking it away. Those hotspots on the other hand do distract a bit, bt other than that i like it.', '2008-04-03 12:06:46.000000', NULL, 1),
(4610733, 665110, 89431, '<td valign="top">The bird and bird seed really bring out the blue hue on that tire. Real nice detail and textures all through out your photo.</td>', 'The bird and bird seed really bring out the blue hue on that tire. Real nice detail and textures all through out your photo.', '2008-04-03 12:14:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4610740, 663560, 89431, '<td valign="top">Its good that church is silhoetted so it doesnt ruin the ''only cool colors" thing, and the sky is nice. Just too much negative space with the church</td>', 'Its good that church is silhoetted so it doesnt ruin the ''only cool colors" thing, and the sky is nice. Just too much negative space with the church', '2008-04-03 12:15:59.000000', NULL, 1),
(4610753, 665112, 89431, '<td valign="top">I do consider white to be both warm and cool depending onthe suroundings so i like what you''ve done here. the framing with the snow looks really cool, and the nmonotoneness (except for the chimney) looks beatiful</td>', 'I do consider white to be both warm and cool depending onthe suroundings so i like what you''ve done here. the framing with the snow looks really cool, and the nmonotoneness (except for the chimney) looks beatiful', '2008-04-03 12:18:05.000000', NULL, 1),
(4610760, 663618, 89431, '<td valign="top">I love this angle and building. Great distortion on the other buildings too. Everything about this seems perfect for the competition.</td>', 'I love this angle and building. Great distortion on the other buildings too. Everything about this seems perfect for the competition.', '2008-04-03 12:19:44.000000', NULL, 1),
(4610768, 665099, 89431, '<td valign="top">Kind of reminds me a bit of <i>corpse bride </i>with the blue hue. I like her expression but the right side of your photo should have been cropped more it gets blurry and boring. (just half an inch i think...) i also like how her arms seem to disapear.</td>', 'Kind of reminds me a bit of corpse bride with the blue hue. I like her expression but the right side of your photo should have been cropped more it gets blurry and boring. (just half an inch i think...) i also like how her arms seem to disapear.', '2008-04-03 12:22:17.000000', NULL, 1),
(4610774, 663496, 89431, '<td valign="top">this looks to contrasted, to black and white, i would have liked to see more shades of blue in the water and a brighter sky.</td>', 'this looks to contrasted, to black and white, i would have liked to see more shades of blue in the water and a brighter sky.', '2008-04-03 12:23:22.000000', NULL, 1),
(4610778, 664681, 89431, '<td valign="top">The bottom half is way too warm, although i do like the pairing of yellow and blue, the yellow is too overpowering.</td>', 'The bottom half is way too warm, although i do like the pairing of yellow and blue, the yellow is too overpowering.', '2008-04-03 12:24:29.000000', NULL, 1),
(4610785, 664987, 89431, '<td valign="top">Beautiful mountain scene, i like how nothing here is actually white. Tghe clouds and the snow all have blue undertones, well done.</td>', 'Beautiful mountain scene, i like how nothing here is actually white. Tghe clouds and the snow all have blue undertones, well done.', '2008-04-03 12:25:49.000000', NULL, 1),
(4610789, 664644, 89431, '<td valign="top">All though the water is a cool blue color the rest of this photo is too warm to score high for me. And as cool as the fallen log looks, at this angle it''s just distracting from the main focus the waterfall.</td>', 'All though the water is a cool blue color the rest of this photo is too warm to score high for me. And as cool as the fallen log looks, at this angle it''s just distracting from the main focus the waterfall.', '2008-04-03 12:27:30.000000', NULL, 1),
(4610794, 663740, 89431, '<td valign="top">I like the added blue tone, it gives a chance for a differnt scene besides water and flower to be consider cool colors. Nice leading line too.</td>', 'I like the added blue tone, it gives a chance for a differnt scene besides water and flower to be consider cool colors. Nice leading line too.', '2008-04-03 12:29:38.000000', NULL, 1),
(4610796, 663834, 89431, '<td valign="top">I love the ice and the mist in the background. The floweritself demands enough attention so none of these elements distract from it. I also like the texture you captured on the petals and ice crystals.</td>', 'I love the ice and the mist in the background. The floweritself demands enough attention so none of these elements distract from it. I also like the texture you captured on the petals and ice crystals.', '2008-04-03 12:30:53.000000', NULL, 1),
(4610800, 664169, 89431, '<td valign="top">I like all the different textures and patterns. green is one of those colors that can get warm depending on the shade, so i would have gone with a more conventionally cool color like purple or blue. I like the repeatition of lines too.</td>', 'I like all the different textures and patterns. green is one of those colors that can get warm depending on the shade, so i would have gone with a more conventionally cool color like purple or blue. I like the repeatition of lines too.', '2008-04-03 12:33:33.000000', NULL, 1),
(4610804, 663191, 89431, '<td valign="top">I like the overall softness of the photo: the silk, her skin, her expression, the pearls, and the background. It creates a unity that brings this photo to a whole other level. And of course her eyes are amazing so i wouldn''t be suprised if this was a ribbon.</td>', 'I like the overall softness of the photo: the silk, her skin, her expression, the pearls, and the background. It creates a unity that brings this photo to a whole other level. And of course her eyes are amazing so i wouldn''t be suprised if this was a ribbon.', '2008-04-03 12:35:40.000000', NULL, 1),
(4610806, 663838, 89431, '<td valign="top">Strawberries wouldn''t have been my bery of choice for cool colors... the splash effect is getting a little tired but i like how the background is solid and dark so it doesn''t distract.</td>', 'Strawberries wouldn''t have been my bery of choice for cool colors... the splash effect is getting a little tired but i like how the background is solid and dark so it doesn''t distract.', '2008-04-03 12:37:02.000000', NULL, 1),
(4610812, 665113, 89431, '<td valign="top">Love thedramatic clouds even though they are hiding most of the blue. I like the beach and wouldnt ever suggest to you to cut off some of that beach with the waves, but there s more yellow in this picture than blue. Beautiful photo, probably not right for the challenge. (6) anyways..</td>', 'Love thedramatic clouds even though they are hiding most of the blue. I like the beach and wouldnt ever suggest to you to cut off some of that beach with the waves, but there s more yellow in this picture than blue. Beautiful photo, probably not right for the challenge. (6) anyways..', '2008-04-03 12:41:52.000000', NULL, 1),
(4610814, 663930, 89431, '<td valign="top">I like how his mouth is open and that is a really good crop job. I also like the amount of detail you were able to capture in this action shot.</td>', 'I like how his mouth is open and that is a really good crop job. I also like the amount of detail you were able to capture in this action shot.', '2008-04-03 12:43:34.000000', NULL, 1),
(4610819, 664224, 89431, '<td valign="top">Nice shadows with the stairs. And the sky looks very vibrant.</td>', 'Nice shadows with the stairs. And the sky looks very vibrant.', '2008-04-03 12:47:21.000000', NULL, 1),
(4610824, 664232, 89431, '<td valign="top">I wish you didn''t cut off the edge of that flower and the border just highlights that, besides being really annoying. Other than that i love yur photo down to the fluffy colorful blurred background</td>', 'I wish you didn''t cut off the edge of that flower and the border just highlights that, besides being really annoying. Other than that i love yur photo down to the fluffy colorful blurred background', '2008-04-03 12:49:15.000000', NULL, 1),
(4610826, 664140, 89431, '<td valign="top">i think the warm colors are a bit too overpowering.</td>', 'i think the warm colors are a bit too overpowering.', '2008-04-03 12:49:47.000000', NULL, 1),
