(4610871, 663118, 23921, '<td valign="top">Wonderful colors</td>', 'Wonderful colors', '2008-04-03 13:11:54.000000', NULL, 1),
(4610976, 664713, 26001, '<td valign="top">stunningly beautiful. i wish you had used just a little less harsh light on the lower bottom part of the rose though (which in turn adds the colorless reflection). it spoils the "mood", deep blue light creates so delicately in the rest of the image. still one of my favourites in the challenge.</td>', 'stunningly beautiful. i wish you had used just a little less harsh light on the lower bottom part of the rose though (which in turn adds the colorless reflection). it spoils the "mood", deep blue light creates so delicately in the rest of the image. still one of my favourites in the challenge.', '2008-04-03 14:04:35.000000', NULL, 1),
(4611012, 664256, 57886, '<td valign="top">I really like this shot - GREAT idea... The only thing is that I don´t find the green color cold at all BUT that is just my oppinion so I´ll give you an 8.... Good luck :o)</td>', 'I really like this shot - GREAT idea... The only thing is that I don´t find the green color cold at all BUT that is just my oppinion so I´ll give you an 8.... Good luck :o)', '2008-04-03 14:34:41.000000', NULL, 1),
