(4613912, 664256, 43774, '<td valign="top">Must be a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=29011" rel="nofollow" target="_blank">Techo</a> or <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=49109" rel="nofollow" target="_blank">eyewave</a> photo! Good job, a bit of dust and hairs on the plates though.</td>', 'Must be a  Techo or  eyewave photo! Good job, a bit of dust and hairs on the plates though.', '2008-04-04 13:42:10.000000', NULL, 1),
(4613913, 664550, 84124, '<td valign="top">right idea, but the post processing is way overdone (maybe on purpose?).</td>', 'right idea, but the post processing is way overdone (maybe on purpose?).', '2008-04-04 13:43:02.000000', NULL, 1),
(4613922, 664704, 84124, '<td valign="top">Wonderful use of light and reflection.</td>', 'Wonderful use of light and reflection.', '2008-04-04 13:44:59.000000', NULL, 1),
(4613939, 664450, 84124, '<td valign="top">This is just breathtaking in it''s simplicity and story.  Sometimes with shots like this I wonder if it''s just personal experience and ones own culture that make this so emotive and moving.  This shot says so much not just about a single experience but if I may get introspective, about farm life in general.  My only 8 of this challenge.  Well done.  too bad you couldn''t go sepia for this challenge.</td>', 'This is just breathtaking in it''s simplicity and story.  Sometimes with shots like this I wonder if it''s just personal experience and ones own culture that make this so emotive and moving.  This shot says so much not just about a single experience but if I may get introspective, about farm life in general.  My only 8 of this challenge.  Well done.  too bad you couldn''t go sepia for this challenge.', '2008-04-04 13:49:46.000000', NULL, 1),
