INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4615263, 663054, 5364, '<td valign="top">A very nice idea, but the blue of the sky has lost it''s smoothness.</td>', 'A very nice idea, but the blue of the sky has lost it''s smoothness.', '2008-04-05 07:59:17.000000', NULL, 1),
(4615268, 664941, 5364, '<td valign="top">I guess you took this is a fairly dark environment, because there appears to be a lot of noise in the dark areas.</td>', 'I guess you took this is a fairly dark environment, because there appears to be a lot of noise in the dark areas.', '2008-04-05 08:04:06.000000', NULL, 1),
(4615273, 664953, 5364, '<td valign="top">This is all rather flat looking as you''ve used flash, and you need to switch off the date marking.</td>', 'This is all rather flat looking as you''ve used flash, and you need to switch off the date marking.', '2008-04-05 08:06:48.000000', NULL, 1),
(4615282, 664762, 5364, '<td valign="top">I feel that as the sky is so pale, you needed to have more "subject", so I would have cropped this into "portrait" shape with just the right-hand kite.</td>', 'I feel that as the sky is so pale, you needed to have more "subject", so I would have cropped this into "portrait" shape with just the right-hand kite.', '2008-04-05 08:12:32.000000', NULL, 1),
(4615288, 664407, 5364, '<td valign="top">I can see why you''ve chosen this to photograph, but I feel you should have removed the box of magazines because all it does is distract from the subject.</td>', 'I can see why you''ve chosen this to photograph, but I feel you should have removed the box of magazines because all it does is distract from the subject.', '2008-04-05 08:14:22.000000', NULL, 1),
(4615298, 662792, 5364, '<td valign="top">If this had been sharp it would have been a very good photo</td>', 'If this had been sharp it would have been a very good photo', '2008-04-05 08:18:22.000000', NULL, 1),
(4615302, 664962, 5364, '<td valign="top">Can''t argue with the cool colour, but you don''t have anything in particular to focus on</td>', 'Can''t argue with the cool colour, but you don''t have anything in particular to focus on', '2008-04-05 08:20:21.000000', NULL, 1),
(4615314, 663634, 5364, '<td valign="top">I feel you might have been better with a more geometric arrangement of the candles as it looks a bit haphazard.</td>', 'I feel you might have been better with a more geometric arrangement of the candles as it looks a bit haphazard.', '2008-04-05 08:26:47.000000', NULL, 1),
(4615319, 664720, 5364, '<td valign="top">I feel that if you had increased the contrast, you would have an image with much more impact</td>', 'I feel that if you had increased the contrast, you would have an image with much more impact', '2008-04-05 08:32:16.000000', NULL, 1),
(4615983, 664644, 5364, '<td valign="top">This would be excellent if that tree-trunk weren''t across the middle.</td>', 'This would be excellent if that tree-trunk weren''t across the middle.', '2008-04-05 10:09:55.000000', NULL, 1),
(4616097, 663618, 91862, '<td valign="top">This is a great architectual shot.  I think this definitely meets the requirement of cool colors!  I really like the curves formed by straight rigid lines.  Well done.</td>', 'This is a great architectual shot.  I think this definitely meets the requirement of cool colors!  I really like the curves formed by straight rigid lines.  Well done.', '2008-04-05 11:41:13.000000', NULL, 1),
(4616100, 665061, 91862, '<td valign="top">I normally don''t like people shot in cool colors, but I think this really works.  Well done.</td>', 'I normally don''t like people shot in cool colors, but I think this really works.  Well done.', '2008-04-05 11:44:41.000000', NULL, 1),
(4616263, 664923, 92241, '<td valign="top">just beautiful</td>', 'just beautiful', '2008-04-05 13:21:58.000000', NULL, 1),
(4616465, 664550, 28029, '<td valign="top">Good Effort. I like the composition but 1) Watch the over-sharpening (white halos) 2) Watch blow-outs (White in sky) 3) Calibrate your monitor (seems a little dark overall  If you send me an original after the challenge is over, I will attempt a different post-processing for you. 5</td>', 'Good Effort. I like the composition but 1) Watch the over-sharpening (white halos) 2) Watch blow-outs (White in sky) 3) Calibrate your monitor (seems a little dark overall  If you send me an original after the challenge is over, I will attempt a different post-processing for you. 5', '2008-04-05 14:57:46.000000', NULL, 1),
(4616725, 665051, 89426, '<td valign="top">I like this because it actually fits cool colors, unlike most of the picture. I really like the dark blue background, and how you made some of the ice look blue.</td>', 'I like this because it actually fits cool colors, unlike most of the picture. I really like the dark blue background, and how you made some of the ice look blue.', '2008-04-05 17:39:45.000000', NULL, 1),
(4616822, 664268, 89426, '<td valign="top">I''m not sure how you got this picture but it is good. The colors by themselves make a great picture, but then the penguin adds a lot. Nice job.</td>', 'I''m not sure how you got this picture but it is good. The colors by themselves make a great picture, but then the penguin adds a lot. Nice job.', '2008-04-05 18:52:51.000000', NULL, 1),
(4616823, 662345, 89426, '<td valign="top">I like this picture, not necessarily for colors, but just in general. The sky is beautiful.</td>', 'I like this picture, not necessarily for colors, but just in general. The sky is beautiful.', '2008-04-05 18:54:01.000000', NULL, 1),
(4616825, 664023, 89426, '<td valign="top">I don''t like the background being so dark but the flower is beautiful.</td>', 'I don''t like the background being so dark but the flower is beautiful.', '2008-04-05 18:54:34.000000', NULL, 1),
(4616827, 664658, 89426, '<td valign="top">I love this picture, just because of the color of the flower. Nice simple photo but it woks well.</td>', 'I love this picture, just because of the color of the flower. Nice simple photo but it woks well.', '2008-04-05 18:55:17.000000', NULL, 1),
(4616830, 663583, 89426, '<td valign="top">I don''t think this fits real well in cool colors, but it is a beautiful image.</td>', 'I don''t think this fits real well in cool colors, but it is a beautiful image.', '2008-04-05 18:56:19.000000', NULL, 1),
(4616831, 664207, 89426, '<td valign="top">This doesn''t really fit in cool colors in my opinion.</td>', 'This doesn''t really fit in cool colors in my opinion.', '2008-04-05 18:56:54.000000', NULL, 1),
(4616833, 663422, 89426, '<td valign="top">The red and yellow doesn''t fit in cool colors, but the dark blue makes up for it.</td>', 'The red and yellow doesn''t fit in cool colors, but the dark blue makes up for it.', '2008-04-05 18:57:27.000000', NULL, 1),
(4616834, 664768, 89426, '<td valign="top">Beautiful capture of cool colors. The lines are great.</td>', 'Beautiful capture of cool colors. The lines are great.', '2008-04-05 18:57:59.000000', NULL, 1),
(4616836, 664450, 89426, '<td valign="top">I don''t consider this cool colors, but nice try.</td>', 'I don''t consider this cool colors, but nice try.', '2008-04-05 19:00:35.000000', NULL, 1),
(4616837, 663730, 89426, '<td valign="top">Beautiful, but the pink takes away a little of the cool color effect.</td>', 'Beautiful, but the pink takes away a little of the cool color effect.', '2008-04-05 19:01:07.000000', NULL, 1),
(4616841, 664877, 89426, '<td valign="top">I really like the idea, color, and set up. Nice job. The lines that you created are great.</td>', 'I really like the idea, color, and set up. Nice job. The lines that you created are great.', '2008-04-05 19:03:06.000000', NULL, 1),
(4616842, 663130, 89426, '<td valign="top">I don''t think yellow and that other color are considered cool colors, but I really like the (photoshop) image.</td>', 'I don''t think yellow and that other color are considered cool colors, but I really like the (photoshop) image.', '2008-04-05 19:03:44.000000', NULL, 1),
(4616844, 662867, 89426, '<td valign="top">I like this image because the fence leads up to lighter colors. Nice job. The title doesn''t fit though.</td>', 'I like this image because the fence leads up to lighter colors. Nice job. The title doesn''t fit though.', '2008-04-05 19:04:37.000000', NULL, 1),
(4616846, 664887, 89426, '<td valign="top">Nice image, but i''m not sure if the light green fits in cool or warm colors. Nice detail on the subject though.</td>', 'Nice image, but i''m not sure if the light green fits in cool or warm colors. Nice detail on the subject though.', '2008-04-05 19:05:47.000000', NULL, 1),
(4616849, 664256, 89426, '<td valign="top">I like the setup and idea a lot. The value in the green is good.</td>', 'I like the setup and idea a lot. The value in the green is good.', '2008-04-05 19:07:13.000000', NULL, 1),
(4616853, 663677, 89426, '<td valign="top">Cool picture and idea. i really like the different lines in the picture.</td>', 'Cool picture and idea. i really like the different lines in the picture.', '2008-04-05 19:08:10.000000', NULL, 1),
(4616996, 664532, 90495, '<td valign="top">Very warm and gentle looking flowers.</td>', 'Very warm and gentle looking flowers.', '2008-04-05 20:24:01.000000', NULL, 1),
(4616998, 665094, 90495, '<td valign="top">Nicely done. I like the lighting very much.</td>', 'Nicely done. I like the lighting very much.', '2008-04-05 20:24:43.000000', NULL, 1),
(4616999, 664777, 90495, '<td valign="top">I seen this scene in this challenge, but with less fog.<br/> <br/>Lovely soft feel to this shot.</td>', 'I seen this scene in this challenge, but with less fog. Lovely soft feel to this shot.', '2008-04-05 20:26:02.000000', NULL, 1),
(4617001, 663655, 90495, '<td valign="top">Beautiful shot. I get the willies when I look down to the left. What mount?</td>', 'Beautiful shot. I get the willies when I look down to the left. What mount?', '2008-04-05 20:27:48.000000', NULL, 1),
(4617003, 664989, 90495, '<td valign="top">Cool action shot. Well done.</td>', 'Cool action shot. Well done.', '2008-04-05 20:28:42.000000', NULL, 1),
(4617343, 664232, 90658, '<td valign="top">Too much editing for my tastes.  But beautiful colors.</td>', 'Too much editing for my tastes.  But beautiful colors.', '2008-04-05 23:52:24.000000', NULL, 1),
(4617348, 664894, 90658, '<td valign="top">I''m not really sure what this is.  I see the "coin" with the cards, but I really can''t figure out what the glass is.  I think you''ve got too much white reflection going on.  Again, not sure because this is obviously an "art shot."</td>', 'I''m not really sure what this is.  I see the "coin" with the cards, but I really can''t figure out what the glass is.  I think you''ve got too much white reflection going on.  Again, not sure because this is obviously an "art shot."', '2008-04-05 23:54:23.000000', NULL, 1),
(4617350, 663882, 90658, '<td valign="top">Interesting use of colors.</td>', 'Interesting use of colors.', '2008-04-05 23:54:48.000000', NULL, 1),
(4617352, 664268, 90658, '<td valign="top">I''m thinking that a sharper focus would have been better.</td>', 'I''m thinking that a sharper focus would have been better.', '2008-04-05 23:55:24.000000', NULL, 1),
(4617354, 663475, 90658, '<td valign="top">The cherry blossom framing is fantastic!  The monument seems a little yellow as opposed to white, but other than that, great.</td>', 'The cherry blossom framing is fantastic!  The monument seems a little yellow as opposed to white, but other than that, great.', '2008-04-05 23:56:23.000000', NULL, 1),
(4617356, 664941, 90658, '<td valign="top">Not my cup of tea!  Art speaks differently to different people.</td>', 'Not my cup of tea!  Art speaks differently to different people.', '2008-04-05 23:57:09.000000', NULL, 1),
(4617358, 665096, 90658, '<td valign="top">I found this to be a soothing shot.</td>', 'I found this to be a soothing shot.', '2008-04-05 23:58:10.000000', NULL, 1),
(4617360, 662657, 90658, '<td valign="top">Very simple and elegent.</td>', 'Very simple and elegent.', '2008-04-05 23:58:57.000000', NULL, 1),
(4617363, 662910, 90658, '<td valign="top">Very soulful shot.  There is an interesting mood captured and depicted here.</td>', 'Very soulful shot.  There is an interesting mood captured and depicted here.', '2008-04-05 23:59:57.000000', NULL, 1),
(4617364, 663699, 90658, '<td valign="top">The whiteness of the sky is muting out the blossoms and grass.</td>', 'The whiteness of the sky is muting out the blossoms and grass.', '2008-04-06 00:00:42.000000', NULL, 1),
(4617365, 663834, 90658, '<td valign="top">This was so stunning in the thumbnail.  When I opened it, I noticed that there was a weensy bit of dead space at the top.</td>', 'This was so stunning in the thumbnail.  When I opened it, I noticed that there was a weensy bit of dead space at the top.', '2008-04-06 00:01:30.000000', NULL, 1),
(4617369, 664953, 90658, '<td valign="top">The date/time stamp makes this extremely snap-shottish.</td>', 'The date/time stamp makes this extremely snap-shottish.', '2008-04-06 00:02:36.000000', NULL, 1),
(4617370, 664018, 90658, '<td valign="top">A little sharper on the focus and this would be really nice.</td>', 'A little sharper on the focus and this would be really nice.', '2008-04-06 00:03:48.000000', NULL, 1),
(4617825, 663838, 88204, '<td valign="top">Great shot but I don''t see any cool colors. Red is warm and the water in the glass has a warm tint as well.</td>', 'Great shot but I don''t see any cool colors. Red is warm and the water in the glass has a warm tint as well.', '2008-04-06 07:34:17.000000', NULL, 1),
(4617829, 663634, 88204, '<td valign="top">Interesting shot but it doesn''t give me a feeling of cool colors. I see that the candles have blue and white flames but I have to assume that was a color adjustment since candles don''t burn white or blue hot. Also, fire is inherently warm so it''s hard for me to think of this as cool. Sorry... I guess I''m missing your point.  :)</td>', 'Interesting shot but it doesn''t give me a feeling of cool colors. I see that the candles have blue and white flames but I have to assume that was a color adjustment since candles don''t burn white or blue hot. Also, fire is inherently warm so it''s hard for me to think of this as cool. Sorry... I guess I''m missing your point.  :)', '2008-04-06 07:36:21.000000', NULL, 1),
