(4620696, 664578, 89425, '<td valign="top">this photo is not objective for the challenge, the subject is not displaying any cool colors.</td>', 'this photo is not objective for the challenge, the subject is not displaying any cool colors.', '2008-04-07 11:00:17.000000', NULL, 1),
